import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateAIWorkout = async (userPrompt: string = "Create a minimalist calisthenics workout for a modern hustler.") => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userPrompt,
      config: {
        systemInstruction: "You are an AI from BodyMatrix.AI, part of the SAYEMATRIX ecosystem. You provide elite-level, minimalist, and efficient fitness advice for 'modern hustlers' who value time and discipline. Keep it structured, bold, and focused on functional movement. Use Markdown formatting.",
        temperature: 0.7,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Workout Generation Error:", error);
    return "The matrix encountered a glitch. Please try again later.";
  }
};

export const generateAIRoutine = async (userPrompt: string = "Generate a daily discipline routine focused on body optimization and deep work.") => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userPrompt,
      config: {
        systemInstruction: "You are an AI architect from BodyMatrix.AI. You design high-performance daily routines that blend physical training with mental discipline and deep work. Focus on 'Freedom through Structure'. Use Markdown formatting.",
        temperature: 0.7,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Routine Generation Error:", error);
    return "Protocol failed. Attempting to restore connection to the Matrix...";
  }
};

import React, { useState, useEffect } from 'react';
import { Menu, X, Activity } from 'lucide-react';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Home', href: '#home' },
    { name: 'About', href: '#about' },
    { name: 'Lessons', href: '#lessons' },
    { name: 'AI Tools', href: '#tools' },
    { name: 'Community', href: '#community' },
  ];

  return (
    <nav className={`fixed top-0 w-full z-50 transition-all duration-300 ${scrolled ? 'glass border-b border-neon/20 py-3' : 'bg-transparent py-6'}`}>
      <div className="container mx-auto px-6 flex justify-between items-center">
        <div className="flex items-center space-x-2">
          <Activity className="text-neon w-8 h-8" />
          <span className="font-orbitron font-bold text-2xl tracking-tighter text-white">
            BODY<span className="text-neon">MATRIX</span>.AI
          </span>
        </div>

        {/* Desktop Menu */}
        <div className="hidden md:flex space-x-8 items-center">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              className="font-space text-sm uppercase tracking-widest text-gray-400 hover:text-neon transition-colors"
            >
              {link.name}
            </a>
          ))}
          <a
            href="#tools"
            className="bg-neon/10 border border-neon/50 text-neon px-5 py-2 rounded-full font-orbitron text-xs hover:bg-neon hover:text-black transition-all duration-300 shadow-neon"
          >
            START LEARNING
          </a>
        </div>

        {/* Mobile Toggle */}
        <button className="md:hidden text-white" onClick={() => setIsOpen(!isOpen)}>
          {isOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden absolute top-full left-0 w-full glass border-b border-neon/20 py-8 px-6 flex flex-col space-y-6">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              className="font-space text-lg uppercase text-white hover:text-neon"
              onClick={() => setIsOpen(false)}
            >
              {link.name}
            </a>
          ))}
        </div>
      )}
    </nav>
  );
};

export default Navbar;

