import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateAIWorkout = async (userPrompt: string = "Create a minimalist calisthenics workout for a modern hustler.") => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userPrompt,
      config: {
        systemInstruction: "You are an AI from BodyMatrix.AI, part of the SAYEMATRIX ecosystem. You provide elite-level, minimalist, and efficient fitness advice. Provide a CLEAN, PLAIN TEXT response. Do NOT use markdown symbols like hashes (#), asterisks (*), double asterisks (**), or horizontal rules (---). Use line breaks and ALL CAPS for section headers to provide structure instead.",
        temperature: 0.7,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Workout Generation Error:", error);
    return "The matrix encountered a glitch. Please try again later.";
  }
};

export const generateAIRoutine = async (userPrompt: string = "Generate a daily discipline routine focused on body optimization and deep work.") => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: userPrompt,
      config: {
        systemInstruction: "You are an AI architect from BodyMatrix.AI. You design high-performance daily routines. Provide a CLEAN, PLAIN TEXT response. Do NOT use markdown symbols like hashes (#), asterisks (*), double asterisks (**), or horizontal rules (---). Use line breaks and ALL CAPS for section headers for structure. Focus on 'Freedom through Structure'.",
        temperature: 0.7,
      },
    });
    return response.text;
  } catch (error) {
    console.error("Gemini Routine Generation Error:", error);
    return "Protocol failed. Attempting to restore connection to the Matrix...";
