import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import About from './components/About';
import LearningHub from './components/LearningHub';
import Tools from './components/Tools';
import Community from './components/Community';
import Footer from './components/Footer';
import FreeLessons from './components/FreeLessons';
import LessonDetail from './components/LessonDetail';
import { LessonCard } from './types';

type View = 'landing' | 'lessons' | 'detail';

const App: React.FC = () => {
  const [view, setView] = useState<View>('landing');
  const [selectedLesson, setSelectedLesson] = useState<LessonCard | null>(null);

  // Simple scroll to top on view change
  useEffect(() => {
    window.scrollTo(0, 0);
  }, [view, selectedLesson]);

  // Fix: Ensure the incoming lesson matches the LessonCard interface
  const handleOpenDetail = (lesson: LessonCard) => {
    setSelectedLesson(lesson);
    setView('detail');
  };

  const handleNavigateHome = () => {
    setView('landing');
    setSelectedLesson(null);
  };

  const handleOpenLessonsList = () => {
    setView('lessons');
    setSelectedLesson(null);
  };

  return (
    <div className="min-h-screen selection:bg-neon selection:text-black">
      <Navbar onNavigateHome={handleNavigateHome} />

      <main>
        {view === 'landing' && (
          <>
            <Hero />
            <About />
            <LearningHub onExploreAll={handleOpenLessonsList} />
            <Tools />
            <Community />
          </>
        )}

        {view === 'lessons' && (
          <FreeLessons 
            onBack={handleNavigateHome} 
            onSelectLesson={handleOpenDetail} 
          />
        )}

        {view === 'detail' && selectedLesson && (
          <LessonDetail 
            lesson={selectedLesson} 
            onBack={handleOpenLessonsList} 
          />
        )}
      </main>

      <Footer 
        onNavigateHome={handleNavigateHome} 
        onExploreAll={handleOpenLessonsList} 
      />

      {/* Decorative Glow Elements */}
      <div className="fixed top-[-10%] left-[-10%] w-[40%] h-[40%] bg-neon/5 rounded-full blur-[150px] pointer-events-none -z-10" />
      <div className="fixed bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-neon/5 rounded-full blur-[150px] pointer-events-none -z-10" />
    </div>
  );
};

export default App;

