import React, { useState, useEffect } from 'react';
import { Menu, X, Activity } from 'lucide-react';

interface NavbarProps {
  onNavigateHome: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ onNavigateHome }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleLinkClick = (e: React.MouseEvent<HTMLAnchorElement>, href: string) => {
    e.preventDefault();
    onNavigateHome();

    // Slight delay to ensure the DOM is ready if we just switched views
    setTimeout(() => {
      const targetId = href.replace('#', '');
      const element = document.getElementById(targetId);
      if (element) {
        const offset = 80; // Account for fixed navbar
        const bodyRect = document.body.getBoundingClientRect().top;
        const elementRect = element.getBoundingClientRect().top;
        const elementPosition = elementRect - bodyRect;
        const offsetPosition = elementPosition - offset;

        window.scrollTo({
          top: offsetPosition,
          behavior: 'smooth'
        });
      }
    }, 10);

    setIsOpen(false);
  };

  const navLinks = [
    { name: 'Home', href: '#home' },
    { name: 'About', href: '#about' },
    { name: 'Lessons', href: '#lessons' },
    { name: 'AI Tools', href: '#tools' },
    { name: 'Community', href: '#community' },
  ];

  return (
    <nav 
      className={`fixed top-0 w-full z-[100] transition-all duration-500 ${
        scrolled 
          ? 'bg-dark/80 backdrop-blur-xl border-b border-white/5 py-4 shadow-[0_4px_30px_rgba(0,0,0,0.5)]' 
          : 'bg-transparent py-8'
      }`}
    >
      <div className="container mx-auto px-6 flex justify-between items-center">
        <div 
          className="flex items-center space-x-3 cursor-pointer group"
          onClick={onNavigateHome}
        >
          <div className="relative">
            <Activity className="text-neon w-8 h-8 transition-transform duration-500 group-hover:rotate-12" />
            <div className="absolute inset-0 bg-neon/20 blur-lg rounded-full opacity-0 group-hover:opacity-100 transition-opacity" />
          </div>
          <span className="font-orbitron font-black text-2xl tracking-tighter text-white uppercase select-none">
            BODY<span className="text-neon text-glow transition-all duration-300 group-hover:brightness-125">MATRIX</span>.AI
          </span>
        </div>

        {/* Desktop Menu */}
        <div className="hidden md:flex space-x-10 items-center">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              onClick={(e) => handleLinkClick(e, link.href)}
              className="font-space text-[11px] font-bold uppercase tracking-[0.3em] text-gray-400 hover:text-neon hover:text-glow transition-all duration-300 relative py-2 group"
            >
              {link.name}
              <span className="absolute bottom-0 left-0 w-0 h-[1px] bg-neon transition-all duration-300 group-hover:w-full" />
            </a>
          ))}
          <button
            onClick={(e: any) => handleLinkClick(e, '#tools')}
            className="ml-4 bg-neon/5 border border-neon/30 text-neon px-6 py-2.5 rounded-xl font-orbitron text-[10px] font-bold tracking-[0.2em] uppercase hover:bg-neon hover:text-black hover:shadow-neon transition-all duration-500"
          >
            START LEARNING
          </button>
        </div>

        {/* Mobile Toggle */}
        <button 
          className="md:hidden text-white p-2 hover:bg-white/5 rounded-lg transition-colors" 
          onClick={() => setIsOpen(!isOpen)}
          aria-label="Toggle Menu"
        >
          {isOpen ? <X size={24} className="text-neon" /> : <Menu size={24} />}
        </button>
      </div>

      {/* Mobile Menu */}
      <div 
        className={`md:hidden absolute top-full left-0 w-full glass border-b border-neon/10 transition-all duration-500 ease-in-out overflow-hidden ${
          isOpen ? 'max-h-[500px] opacity-100 py-10' : 'max-h-0 opacity-0 py-0'
        }`}
      >
        <div className="container mx-auto px-6 flex flex-col space-y-8">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              onClick={(e) => handleLinkClick(e, link.href)}
              className="font-space text-sm font-bold uppercase tracking-[0.4em] text-white hover:text-neon transition-colors"
            >
              {link.name}
            </a>
          ))}
          <button
            onClick={(e: any) => handleLinkClick(e, '#tools')}
            className="w-full bg-neon text-black py-4 rounded-xl font-orbitron text-xs font-bold tracking-[0.2em] uppercase shadow-neon"
          >
            START LEARNING
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

