import React, { useState } from 'react';
import { Brain, TrendingUp, Loader2, X, Download } from 'lucide-react';
import { generateAIWorkout, generateAIRoutine } from '../services/geminiService';

const Tools: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<string | null>(null);
  const [activeTool, setActiveTool] = useState<'workout' | 'routine' | null>(null);

  const sanitizeAIOutput = (text: string) => {
    return text
      .replace(/[#*]/g, '')
      .replace(/---/g, '')
      .trim();
  };

  const handleToolClick = async (type: 'workout' | 'routine') => {
    setLoading(true);
    setActiveTool(type);
    setResult(null);

    try {
      let output = '';
      if (type === 'workout') {
        output = await generateAIWorkout();
      } else {
        output = await generateAIRoutine();
      }

      const cleanOutput = sanitizeAIOutput(output);
      setResult(cleanOutput);
    } catch (e) {
      setResult("Protocol extraction failed. Please re-synchronize.");
    } finally {
      setLoading(false);
    }
  };

  const downloadAsPDF = async () => {
    if (!result || !activeTool) return;

    try {
      const { jsPDF } = await import('https://esm.sh/jspdf');
      const doc = new jsPDF();

      const title = activeTool === 'workout' ? 'TACTICAL MOVEMENT PLAN' : 'DISCIPLINE ARCHITECTURE';
      const timestamp = new Date().toLocaleString();

      doc.setFont("helvetica", "bold");
      doc.setFontSize(24);
      doc.setTextColor(163, 255, 18);
      doc.text("BODYMATRIX.AI", 20, 25);

      doc.setFontSize(14);
      doc.setTextColor(60, 60, 60);
      doc.text("SAYEMATRIX ECOSYSTEM PROTOCOL", 20, 32);

      doc.setFont("helvetica", "bold");
      doc.setFontSize(18);
      doc.setTextColor(0, 0, 0);
      doc.text(title, 20, 50);

      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);
      doc.setTextColor(120, 120, 120);
      doc.text(`Generated: ${timestamp}`, 20, 57);

      doc.setDrawColor(163, 255, 18);
      doc.setLineWidth(1);
      doc.line(20, 62, 190, 62);

      doc.setFont("helvetica", "normal");
      doc.setFontSize(11);
      doc.setTextColor(40, 40, 40);

      const splitText = doc.splitTextToSize(result, 170);
      doc.text(splitText, 20, 75);

      const pageHeight = doc.internal.pageSize.height;
      doc.setFontSize(9);
      doc.setTextColor(180, 180, 180);
      doc.text("© bodymatrix.ai | Free High-Performance Learning Hub", 20, pageHeight - 15);
      doc.text("Freedom through Structure.", 150, pageHeight - 15);

      const fileName = `bodymatrix-${activeTool}-${new Date().toISOString().split('T')[0]}.pdf`;
      doc.save(fileName);
    } catch (error) {
      console.error("PDF Generation failed:", error);
      window.print();
    }
  };

  const closeModal = () => {
    setResult(null);
    setActiveTool(null);
  };

  return (
    <section id="tools" className="py-16 sm:py-24 md:py-32 bg-dark relative overflow-hidden scroll-mt-24">
      {/* Background Decor */}
      <div className="absolute -bottom-24 -left-24 w-48 sm:w-64 h-48 sm:h-64 bg-neon/10 rounded-full blur-[80px] md:blur-[100px]" />

      <div className="container mx-auto px-6 text-center relative z-10">
        <span className="text-neon font-space uppercase tracking-[0.4em] text-[10px] sm:text-xs font-bold mb-4 block">Engineered Optimization</span>
        <h2 className="font-orbitron text-2xl sm:text-3xl md:text-4xl lg:text-5xl font-bold mb-6 md:mb-8 text-white uppercase tracking-tight">AI ARCHITECT TOOLS</h2>
        <p className="font-space text-gray-400 max-w-2xl mx-auto mb-10 md:mb-16 text-sm sm:text-base md:text-lg leading-relaxed">
          Generate custom blueprints for your transformation. Powered by high-performance AI engines and BodyMatrix expertise.
        </p>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 sm:gap-6 md:gap-8 max-w-4xl mx-auto">
          <button 
            onClick={() => handleToolClick('workout')}
            disabled={loading}
            className="flex flex-col items-center justify-center p-6 sm:p-8 md:p-12 glass border border-white/5 hover:border-neon transition-all group relative overflow-hidden rounded-2xl md:rounded-3xl"
          >
            <div className="w-12 h-12 md:w-16 md:h-16 bg-neon/5 rounded-full flex items-center justify-center mb-6 border border-neon/20 group-hover:scale-110 group-hover:bg-neon/10 transition-all">
              <Brain className="text-neon w-6 h-6 md:w-8 md:h-8" />
            </div>
            <h3 className="font-orbitron text-lg sm:text-xl md:text-2xl text-white mb-2 uppercase group-hover:text-neon transition-colors">🧠 AI Workout</h3>
            <p className="font-space text-gray-500 text-xs sm:text-sm">Minimalist movement protocols for your context.</p>
          </button>

          <button 
            onClick={() => handleToolClick('routine')}
            disabled={loading}
            className="flex flex-col items-center justify-center p-6 sm:p-8 md:p-12 glass border border-white/5 hover:border-neon transition-all group relative overflow-hidden rounded-2xl md:rounded-3xl"
          >
            <div className="w-12 h-12 md:w-16 md:h-16 bg-neon/5 rounded-full flex items-center justify-center mb-6 border border-neon/20 group-hover:scale-110 group-hover:bg-neon/10 transition-all">
              <TrendingUp className="text-neon w-6 h-6 md:w-8 md:h-8" />
            </div>
            <h3 className="font-orbitron text-lg sm:text-xl md:text-2xl text-white mb-2 uppercase group-hover:text-neon transition-colors">📈 AI Routine</h3>
            <p className="font-space text-gray-500 text-xs sm:text-sm">Structured discipline for high-performance living.</p>
          </button>
        </div>

        {loading && (
          <div className="mt-8 sm:mt-12 md:mt-16 flex flex-col items-center gap-4 text-neon">
            <Loader2 className="animate-spin w-8 h-8 sm:w-10 sm:h-10 md:w-12 md:h-12" />
            <p className="font-space text-[9px] sm:text-[10px] md:text-sm tracking-widest uppercase animate-pulse">Connecting to Matrix Intelligence...</p>
          </div>
        )}
      </div>

      {/* Result Modal */}
      {result && (activeTool) && (
        <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 sm:p-6 bg-black/95 backdrop-blur-lg overflow-hidden">
          <div className="bg-dark-lighter border border-neon/30 w-full max-w-3xl max-h-[85vh] sm:max-h-[90vh] overflow-y-auto relative p-6 sm:p-8 md:p-10 rounded-2xl md:rounded-3xl shadow-[0_0_50px_rgba(163,255,18,0.15)] custom-scrollbar">
            <button 
              onClick={closeModal}
              className="absolute top-4 right-4 text-gray-500 hover:text-neon transition-colors p-2"
            >
              <X size={24} className="md:w-8 md:h-8" />
            </button>
            <div className="mb-6 sm:mb-8 md:mb-10">
              <span className="text-neon font-orbitron text-[9px] sm:text-[10px] md:text-xs tracking-widest uppercase mb-2 block">Protocol Restored</span>
              <h2 className="font-orbitron text-xl sm:text-2xl md:text-3xl font-bold text-white mb-4 uppercase leading-tight">
                {activeTool === 'workout' ? 'Tactical Movement Plan' : 'Discipline Architecture'}
              </h2>
              <div className="w-12 sm:w-16 md:w-20 h-1 bg-neon" />
            </div>
            <div className="prose prose-invert max-w-none text-gray-300 font-space text-sm sm:text-base md:text-lg whitespace-pre-wrap leading-relaxed">
